import struct
dec = bytes.fromhex('377f0682002de218000010000000000090986c150e93e601ea539ba3a4220656')
stored = struct.unpack('>II', dec[24:32])
print("stored:", hex(stored[0]), hex(stored[1]))

def words(b, endian='>'):
    return list(struct.unpack(endian + 'I'*(len(b)//4), b))

def v1(data, s0=0, s1=0):  # s0+=X+s1; s1+=Y+s0 per 8-byte pair, big-endian
    w = words(data)
    for i in range(0, len(w), 2):
        s0 = (s0 + w[i] + s1) & 0xFFFFFFFF
        s1 = (s1 + w[i+1] + s0) & 0xFFFFFFFF
    return s0, s1

def v1le(data, s0=0, s1=0):
    w = words(data, '<')
    for i in range(0, len(w), 2):
        s0 = (s0 + w[i] + s1) & 0xFFFFFFFF
        s1 = (s1 + w[i+1] + s0) & 0xFFFFFFFF
    return s0, s1

for n in (8, 16, 24, 32):
    print(f"v1  first {n}B:", tuple(hex(x) for x in v1(dec[:n])), "MATCH" if v1(dec[:n])==stored else "")
    print(f"v1le first {n}B:", tuple(hex(x) for x in v1le(dec[:n])), "MATCH" if v1le(dec[:n])==stored else "")
